import React, { useState } from 'react';
import { Upload, FileText, CheckCircle, Sparkles } from 'lucide-react';

export const WelcomeScreen = ({ onFileUpload, fileInputRef }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isHovering, setIsHovering] = useState(false);

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);

    const files = e.dataTransfer.files;
    if (files.length > 0) {
      const file = files[0];
      const fileType = file.name.split('.').pop().toLowerCase();
      if (['pdf', 'docx'].includes(fileType)) {
        // Create a synthetic event to pass to onFileUpload
        const syntheticEvent = {
          target: { files: [file] }
        };
        onFileUpload(syntheticEvent);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[600px] p-8">
      {/* Animated Background Elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-20 left-10 w-72 h-72 bg-indigo-200 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-blob"></div>
        <div className="absolute top-40 right-10 w-72 h-72 bg-purple-200 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-blob animation-delay-2000"></div>
        <div className="absolute bottom-20 left-1/2 w-72 h-72 bg-pink-200 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-blob animation-delay-4000"></div>
      </div>

      {/* Main Content */}
      <div className="relative z-10 max-w-2xl w-full">
        {/* Header with Animation */}
        <div className="text-center mb-8 animate-fade-in">
          <div className="inline-flex items-center justify-center mb-4">
            <Sparkles className="w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h1 className="text-4xl font-bold text-gray-900 mb-3 bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
            Welcome to Your AI Interview
          </h1>
          <p className="text-lg text-gray-600">
            Let's get started on your journey to success
          </p>
        </div>

        {/* Drag & Drop Zone */}
        <div
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          className={`relative bg-white rounded-2xl shadow-2xl p-12 transition-all duration-300 transform hover:scale-[1.02] ${
            isDragging ? 'border-4 border-indigo-500 scale-105 bg-indigo-50' : 'border-4 border-transparent'
          }`}
        >
          {/* Upload Icon with Animation */}
          <div className="flex justify-center mb-6">
            <div className={`relative transition-transform duration-500 ${isDragging ? 'scale-110 rotate-12' : ''}`}>
              <div className="absolute inset-0 bg-indigo-400 rounded-full blur-2xl opacity-40 animate-pulse"></div>
              <div className="relative bg-gradient-to-br from-indigo-500 to-purple-600 p-6 rounded-full">
                <Upload className="w-16 h-16 text-white" />
              </div>
            </div>
          </div>

          {/* Main Text */}
          <div className="text-center mb-8">
            <h2 className="text-2xl font-bold text-gray-800 mb-3">
              {isDragging ? 'Drop your resume here!' : 'Upload Your Resume'}
            </h2>
            <p className="text-gray-600 mb-2">
              Drag and drop your file here, or click to browse
            </p>
            <p className="text-sm text-gray-500">
              We'll analyze your experience and create personalized questions
            </p>
          </div>

          {/* Upload Button */}
          <div className="flex justify-center mb-6">
            <button
              onClick={() => fileInputRef.current?.click()}
              onMouseEnter={() => setIsHovering(true)}
              onMouseLeave={() => setIsHovering(false)}
              className="relative group"
            >
              <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-purple-600 rounded-xl blur opacity-50 group-hover:opacity-100 transition duration-300"></div>
              <div className="relative bg-gradient-to-r from-indigo-600 to-purple-600 text-white px-10 py-4 rounded-xl font-semibold text-lg shadow-lg transform transition-all duration-200 hover:scale-105 active:scale-95 flex items-center gap-3">
                <FileText className={`w-5 h-5 transition-transform duration-300 ${isHovering ? 'rotate-12' : ''}`} />
                Choose File
              </div>
            </button>
          </div>

          {/* Hidden File Input */}
          <input
            ref={fileInputRef}
            type="file"
            accept=".pdf,.docx"
            onChange={onFileUpload}
            className="hidden"
          />

          {/* Features Grid */}
          <div className="grid grid-cols-3 gap-4 mt-8 pt-8 border-t border-gray-200">
            <div className="text-center group cursor-pointer">
              <div className="bg-green-100 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-2 group-hover:bg-green-200 transition-colors">
                <CheckCircle className="w-6 h-6 text-green-600" />
              </div>
              <p className="text-sm font-medium text-gray-700">PDF Support</p>
            </div>
            <div className="text-center group cursor-pointer">
              <div className="bg-blue-100 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-2 group-hover:bg-blue-200 transition-colors">
                <CheckCircle className="w-6 h-6 text-blue-600" />
              </div>
              <p className="text-sm font-medium text-gray-700">DOCX Support</p>
            </div>
            <div className="text-center group cursor-pointer">
              <div className="bg-purple-100 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-2 group-hover:bg-purple-200 transition-colors">
                <Sparkles className="w-6 h-6 text-purple-600" />
              </div>
              <p className="text-sm font-medium text-gray-700">AI-Powered</p>
            </div>
          </div>
        </div>

        {/* Bottom Info */}
        <div className="text-center mt-8 animate-fade-in-delay">
          <p className="text-sm text-gray-500 mb-2">
            🔒 Your data is secure and processed locally
          </p>
          <p className="text-xs text-gray-400">
            Supported formats: PDF, DOCX • Max size: 10MB
          </p>
        </div>
      </div>

      {/* Custom Animations */}
      <style jsx>{`
        @keyframes blob {
          0%, 100% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(20px, -50px) scale(1.1); }
          50% { transform: translate(-20px, 20px) scale(0.9); }
          75% { transform: translate(50px, 50px) scale(1.05); }
        }

        @keyframes fade-in {
          from { opacity: 0; transform: translateY(-20px); }
          to { opacity: 1; transform: translateY(0); }
        }

        .animate-blob {
          animation: blob 7s infinite;
        }

        .animation-delay-2000 {
          animation-delay: 2s;
        }

        .animation-delay-4000 {
          animation-delay: 4s;
        }

        .animate-fade-in {
          animation: fade-in 0.8s ease-out;
        }

        .animate-fade-in-delay {
          animation: fade-in 0.8s ease-out 0.3s both;
        }
      `}</style>
    </div>
  );
};
